mod pic;mod models;mod transport;
use hec_native_ic::{counted,instance::pick_instance,rng::Rng,poly::Poly,jac::Div};
fn main(){counted::disable();let inst=pick_instance(61,3).unwrap();assert_eq!(inst.c,5);assert_eq!(inst.ell,124459);let c=&inst.curve;let mut rng=Rng::new(2026111800^61^(3<<32));let fixtures=(0..2).map(|case|{let multiple=if case==0{1}else{17};let d=c.mul(&inst.d1,multiple);let expected=1+rng.below(inst.ell-1);let t=c.mul(&d,expected);(case,multiple,d,t,expected)}).collect::<Vec<_>>();let models=models::models();assert_eq!(models.len(),2);for(map,model)in models.iter().enumerate(){let p0=pic::first_rational_point_canonical(61,&model.coeff).unwrap();let pc=pic::PlaneQuartic::new(61,model.coeff,p0).unwrap();println!("MODEL map={map} p0={p0:?} independent_module_smoothness=true setup={:?}",pc.setup_cost());let zero=transport::transport(c,&c.zero(),&inst.d1,model,&pc,1).unwrap();assert!(pc.is_zero(&zero.class));
for(case,multiple,d,t,expected)in &fixtures{let before=pc.counter();let sd=transport::transport(c,d,&inst.d1,model,&pc,1).expect("bounded source transport exhausted");let st=transport::transport(c,t,&inst.d1,model,&pc,1).expect("bounded target transport exhausted");let source_again=transport::transport(c,d,&inst.d1,model,&pc,37).unwrap();let target_again=transport::transport(c,t,&inst.d1,model,&pc,37).unwrap();assert_eq!(sd.class,source_again.class,"auxiliary source dependence");assert_eq!(st.class,target_again.class,"auxiliary target dependence");assert!(!pc.is_zero(&sd.class));assert!(pc.is_zero(&pc.mul_scalar(&sd.class,inst.ell as u128)));assert_eq!(pc.mul_scalar(&sd.class,*expected as u128),st.class,"original scalar not preserved");let negative=transport::transport(c,&c.neg(d),&inst.d1,model,&pc,1).unwrap();assert_eq!(negative.class,pc.neg(&sd.class));let twice=transport::transport(c,&c.mul(d,2),&inst.d1,model,&pc,1).unwrap();let triple=transport::transport(c,&c.mul(d,3),&inst.d1,model,&pc,1).unwrap();let five=transport::transport(c,&c.mul(d,5),&inst.d1,model,&pc,1).unwrap();assert_eq!(twice.class,pc.double(&sd.class));assert_eq!(pc.add(&twice.class,&triple.class),five.class);let delta=(1..61).find(|&z|!c.is_valid(&Div{u:d.u,v:d.v.add(&Poly::constant(z),&c.fp)})).unwrap();let invalid=Div{u:d.u,v:d.v.add(&Poly::constant(delta),&c.fp)};assert!(transport::transport(c,&invalid,&inst.d1,model,&pc,1).is_none());println!("FIXTURE map={map} case={case} source_multiple={multiple} ell={} source_u={:?} source_v={:?} target_u={:?} target_v={:?} expected_driver_scalar={expected} source_aux={} target_aux={} alternate_source_aux={} alternate_target_aux={} rejected={} source_class={:?} target_class={:?} scalar_preserved=true source_nonzero=true subgroup_order_check=true auxiliary_independent=true negation=true additive_controls=true invalid_rejected=true quartic_arithmetic={:?}",inst.ell,&d.u.c[..d.u.n],&d.v.c[..d.v.n],&t.u.c[..t.u.n],&t.v.c[..t.v.n],sd.aux_scalar,st.aux_scalar,source_again.aux_scalar,target_again.aux_scalar,sd.rejected+st.rejected+source_again.rejected+target_again.rejected,sd.class.key(),st.class.key(),pc.counter().since(&before));}
println!("MAP map={map} stats={:?}",pc.stats());}eprintln!("PASS maps=2 original_fixtures=4 source_target_scalar_preserved=true auxiliary_independent=true nonzero_order_ell=true additive_and_negative_controls=true no_quartic_dlp_execution_or_speed_claim=true");}
